// Joins the PJSR sources into build/pjsr/mcp-handlers.js, the one file each driver script
// includes. Function declarations are hoisted and no top level variable depends on another
// file, so the order is for reading only.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = path.join(repoRoot, "build", "pjsr", "mcp-handlers.js");

const PJSR_SOURCES = [
  "pjsr/core.js",
  "pjsr/images.js",
  "pjsr/processes.js",
  "pjsr/script-controls.js",
  "pjsr/script-engines.js",
  "pjsr/scripts.js",
  "pjsr/history.js",
  "pjsr/measure-common.js",
  "pjsr/measure-noise.js",
  "pjsr/measure-gradient.js",
  "pjsr/measure-neutrality.js",
  "pjsr/measure-stars.js",
  "pjsr/measure-structure-color.js",
  "pjsr/render.js",
  "pjsr/export.js",
  "pjsr/dispatch.js",
];

// PixInsight's preprocessor reads a slash star as the start of a block comment even inside a line
// comment, string or regex, and swallows the code up to the next star slash, so every driver fails
// to parse. The pjsr files use line comments only.
const BLOCK_COMMENT_MARK = /\/\*/;

const lines = ["// Generated by scripts/build-pjsr-bundle.mjs from the files in pjsr/. Do not edit.", ""];
const problems = [];
for (const source of PJSR_SOURCES) {
  lines.push(`// ---- ${source} ----`);
  fs.readFileSync(path.join(repoRoot, source), "utf8").split(/\r?\n/).forEach((line, index) => {
    if (BLOCK_COMMENT_MARK.test(line)) problems.push(`${source}:${index + 1}: ${line.trim()}`);
    lines.push(line);
  });
  lines.push("");
}
if (problems.length) {
  console.error("Block comment marks break PixInsight's preprocessor, reword these lines:");
  for (const problem of problems) console.error(`  ${problem}`);
  process.exit(1);
}

fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, lines.join("\n"), "utf8");
console.log(`wrote ${path.relative(repoRoot, outputPath)} (${lines.length} lines)`);
